namespace Wholesale.AdminWinForms;

internal static class UiTheme
{
    public static Color Ink = Color.FromArgb(24, 54, 56), Green = Color.FromArgb(36, 113, 93), Muted = Color.FromArgb(103, 122, 121), Background = Color.FromArgb(244, 246, 242), Line = Color.FromArgb(221, 230, 225);
    public static Button Button(string text, EventHandler action, bool primary = false) { var b = new Button { Tag=primary?"primary":"secondary", Text = text, AutoSize = true, MinimumSize = new(105, 42), Height = 42, FlatStyle = FlatStyle.Flat, BackColor = primary ? Green : Color.White, ForeColor = primary ? Color.White : Ink, Font = new("Segoe UI", 10, FontStyle.Bold), Margin = new(0, 0, 10, 0), Cursor = Cursors.Hand, Padding = new(10, 0, 10, 0) }; b.FlatAppearance.BorderColor = Line; b.FlatAppearance.BorderSize = primary ? 0 : 1; b.FlatAppearance.MouseOverBackColor = primary ? Color.FromArgb(48, 128, 100) : Color.FromArgb(241, 246, 239); b.FlatAppearance.MouseDownBackColor = primary ? Color.FromArgb(29, 91, 69) : Color.FromArgb(231, 239, 229); b.Click += action; return b; }
    public static void Dialog(Form form) { form.BackColor = Background; form.ForeColor = Ink; form.Font = new("Segoe UI", 11); form.AutoScaleMode = AutoScaleMode.Dpi; form.Padding = new(10); foreach (Control c in form.Controls) Decorate(c); }
    private static void Decorate(Control c) { if (c is Button b) { b.BackColor = Green; b.ForeColor = Color.White; b.FlatStyle = FlatStyle.Flat; b.FlatAppearance.BorderSize = 0; b.Font = new("Segoe UI", 11, FontStyle.Bold); } if (c is TextBox t) t.BorderStyle = BorderStyle.FixedSingle; foreach (Control child in c.Controls) Decorate(child); }
    public static DataGridView Grid() => new() { Dock = DockStyle.Fill, AutoGenerateColumns = true, ReadOnly = true, AllowUserToAddRows = false, AllowUserToDeleteRows = false, MultiSelect = false, SelectionMode = DataGridViewSelectionMode.FullRowSelect, AutoSizeColumnsMode = DataGridViewAutoSizeColumnsMode.Fill, RowHeadersVisible = false, BorderStyle = BorderStyle.None, BackgroundColor = Color.White, GridColor = Line, EnableHeadersVisualStyles = false, ColumnHeadersHeight = 45, ColumnHeadersHeightSizeMode = DataGridViewColumnHeadersHeightSizeMode.DisableResizing, RowTemplate = { Height = 48 }, DefaultCellStyle = new() { Font = new("Segoe UI", 10), ForeColor = Ink, SelectionBackColor = Color.FromArgb(228, 239, 225), SelectionForeColor = Ink, Padding = new Padding(10, 6, 10, 6) }, ColumnHeadersDefaultCellStyle = new() { BackColor = Color.FromArgb(238, 243, 235), ForeColor = Muted, Font = new("Segoe UI", 9, FontStyle.Bold), Padding = new Padding(10, 0, 10, 0) }, AlternatingRowsDefaultCellStyle = new() { BackColor = Color.FromArgb(250, 252, 248) } };
}
